    "formatName": "mov,mp4 (AVFoundation adapter)"
  },
  "transcript": {
    "segments": [
      {
        "start": 0,
        "end": 1.72,
        "text": "梁文峰最近聊到下一代模型"
      },
      {
        "start": 1.72,
        "end": 2.68,
        "text": "说了两件事情"
      },
      {
        "start": 2.68,
        "end": 4.08,
        "text": "第一件就是持续学习"
      },
      {
        "start": 4.08,
        "end": 6,
        "text": "是通向超级智能的下一个台阶"
      },
      {
        "start": 6,
        "end": 8.08,
        "text": "第二件事情就是目前没有找到"
      },
      {
        "start": 8.08,
        "end": 9.28,
        "text": "特别有效的解决方案"
      },
      {
        "start": 9.28,
        "end": 10.68,
        "text": "大家都在找更好的方法"
      },
      {
        "start": 10.68,
        "end": 12.32,
        "text": "那为什么持续学习这么重要呢"
      },
      {
        "start": 12.32,
        "end": 14.24,
        "text": "卡巴西还不知道谁来之前举个一个例子"
      },
      {
        "start": 14.24,
        "end": 15.08,
        "text": "我觉得很形象"
      },
      {
        "start": 15.08,
        "end": 17.48,
        "text": "就是想象有一个人第一次学Sax"
      },
      {
        "start": 17.48,
        "end": 18.24,
        "text": "他失败了"
      },
      {
        "start": 18.24,
        "end": 20.32,
        "text": "然后写下了自己很多的新德笔记"
      },
      {
        "start": 20.32,
        "end": 21.48,
        "text": "下一个学生进来之后呢"
      },
      {
        "start": 21.48,
        "end": 22.76,
        "text": "读了他这些新德笔记"
      },
      {
        "start": 22.76,
        "end": 23.76,
        "text": "当然也没学会"
      },
      {
        "start": 23.76,
        "end": 26,
        "text": "然后继续加上自己的这些学习新德"
      },
      {
        "start": 26,
        "end": 27.6,
        "text": "外面排着无穷多的学生"
      },
      {
        "start": 27.6,
        "end": 28.56,
        "text": "每个人进来的时候"
      },
      {
        "start": 28.56,
        "end": 31,
        "text": "都给下一个人去写很多的这个新德笔记"
      },
      {
        "start": 31,
        "end": 31.92,
        "text": "那大家可以想象"
      },
      {
        "start": 31.92,
        "end": 33.6,
        "text": "就不管这个新德写得多好"
      },
      {
        "start": 33.6,
        "end": 34.36,
        "text": "笔记写得多厚"
      },
      {
        "start": 34.36,
        "end": 35.76,
        "text": "后来的学生进来之后"
      },
      {
        "start": 35.76,
        "end": 37.96,
        "text": "还是没有办法第一次就把Sax吹得很好"
      },
      {
        "start": 37.96,
        "end": 39.16,
        "text": "要真正学会"
      },
      {
        "start": 39.16,
        "end": 41.24,
        "text": "必须把经验累计进大桃里面"
      },
      {
        "start": 41.24,
        "end": 42.28,
        "text": "AI也是一样的"
      },
      {
        "start": 42.28,
        "end": 44.4,
        "text": "比如说像现在的Raggy"
      },
      {
        "start": 44.4,
        "end": 45.6,
        "text": "T-Z工程"
      },
      {
        "start": 45.6,
        "end": 47.52,
        "text": "本质上还是用中笔记本的方案"
      },
      {
        "start": 47.52,
        "end": 48.92,
        "text": "每次都是把经验"
      },
      {
        "start": 48.92,
        "end": 50.52,
        "text": "然后写成文档之后"
      },
      {
        "start": 50.52,
        "end": 51.8,
        "text": "塞进上下文窗口"
      },
      {
        "start": 51.8,
        "end": 52.72,
        "text": "让模型去读一遍"
      },
      {
        "start": 52.72,
        "end": 54.64,
        "text": "模型本身并没有变得更强"
      },
      {
        "start": 54.64,
        "end": 57.64,
        "text": "这些方案就像上面那个吹Sax的例子一样"
      },
      {
        "start": 57.64,
        "end": 60.28,
        "text": "很难让模型第一次就去学会"
      },
      {
        "start": 60.28,
        "end": 62.84,
        "text": "很多的这些人类的方法 经验"
      },
      {
        "start": 62.84,
        "end": 64.8,
        "text": "但现在全世界的研究员和创业者"
      },
      {
        "start": 64.8,
        "end": 65.92,
        "text": "其实都在找自己的方案"
      },
      {
        "start": 65.92,
        "end": 67.32,
        "text": "今天我觉得跟大家分享一个"
      },
      {
        "start": 67.32,
        "end": 69.48,
        "text": "我最近看到的贵伍团对Tradjector类的思路"
      },
      {
        "start": 69.48,
        "end": 71.88,
        "text": "他们最近在一个AI工程的闭门分享"
      },
      {
        "start": 71.88,
        "end": 73.52,
        "text": "这个会议里面聊了自己的项目"
      },
      {
        "start": 73.52,
        "end": 76.32,
        "text": "然后几个连创的分别来自于苹果"
      },
      {
        "start": 76.32,
        "end": 78.28,
        "text": "Windserv和DVMine的这些"
      },
      {
        "start": 78.28,
        "end": 79.92,
        "text": "现在最前线的这些大厂"
      },
      {
        "start": 79.92,
        "end": 81.28,
        "text": "他们在做的一件事情"
      },
      {
        "start": 81.28,
        "end": 82.92,
        "text": "就是给AI去搭建一个"
      },
      {
        "start": 82.92,
        "end": 84.72,
        "text": "持续学习的这样的平台"
      },
      {
        "start": 84.72,
        "end": 85.64,
        "text": "听到他的分享之后"
      },
      {
        "start": 85.64,
        "end": 87.4,
        "text": "我觉得非常有企发有说话"
      },
      {
        "start": 87.4,
        "end": 89.48,
        "text": "我觉得可能对在创业多项目"
      },
      {
        "start": 89.48,
        "end": 92.96000000000001,
        "text": "或者是在企业里想要去落地AI的这些朋友们"
      },
      {
        "start": 92.96000000000001,
        "end": 94.84,
        "text": "你们听了之后肯定也会有很多的收获"
      },
      {
        "start": 94.84,
        "end": 96.44,
        "text": "第一点他们聊到的是说"
      },
      {
        "start": 96.44,
        "end": 97.44,
        "text": "AI不缺智商"
      },
      {
        "start": 97.44,
        "end": 98.64,
        "text": "其实缺的是经验"
      },
      {
        "start": 98.64,
        "end": 99.88,
        "text": "Tradjector的判断是"
      },
      {
        "start": 99.88,
        "end": 102.47999999999999,
        "text": "就是模型在IQ智商这个轴上面"
      },
      {
        "start": 102.47999999999999,
        "end": 103.47999999999999,
        "text": "其实越来越强"
      },
      {
        "start": 103.47999999999999,
        "end": 105.12,
        "text": "每周都有新的模型去刷榜"
      },
      {
        "start": 105.12,
        "end": 106.24000000000001,
        "text": "但不管多聪明"
      },
      {
        "start": 106.24000000000001,
        "end": 107.68,
        "text": "你跟他们聊天对话的时候"
      },
      {
        "start": 107.68,
        "end": 110.12,
        "text": "永远像是说他们第一天入职一样"
      },
      {
        "start": 110.12,
        "end": 110.88,
        "text": "他们打了一个比方"
      },
      {
        "start": 110.88,
        "end": 112.12,
        "text": "比如说你口袋里面"
      },
      {
        "start": 112.12,
        "end": 114,
        "text": "装了一个数学家陶哲圈"
      },
      {
        "start": 114,
        "end": 114.68,
        "text": "很厉害对吧"
      },
      {
        "start": 114.68,
        "end": 118.44,
        "text": "无敌 第一天到一个比说你的快迹是无所里面去上班"
      },
      {
        "start": 118.44,
        "end": 120.84,
        "text": "那他大概率不是那里面最好的快迹"
      },
      {
        "start": 120.84,
        "end": 122.52,
        "text": "可能也不是那里面前五的快迹"
      },
      {
        "start": 122.52,
        "end": 124.08,
        "text": "这里面差的当然不是智商"
      },
      {
        "start": 124.08,
        "end": 124.8,
        "text": "是经验"
      },
      {
        "start": 124.8,
        "end": 125.52,
        "text": "给他几天时间"
      },
      {
        "start": 125.52,
        "end": 127.48,
        "text": "他可能就能成为那里面的脚摇折了"
      },
      {
        "start": 127.48,
        "end": 130.08,
        "text": "这个例子就是他们所说的Experience gap"
      },
      {
        "start": 130.08,
        "end": 130.96,
        "text": "经验的红钩"
      },
      {
        "start": 130.96,
        "end": 131.96,
        "text": "但我们缺这个嘛"
      },
      {
        "start": 131.96,
        "end": 132.8,
        "text": "其实是不缺的"
      },
      {
        "start": 132.8,
        "end": 134.72,
        "text": "这个经验素材现在到处都是"
      },
      {
        "start": 134.72,
        "end": 137.76,
        "text": "因为现在每天都有海量的Agent交互在发生"
      },
      {
        "start": 137.76,
        "end": 139.32,
        "text": "在办公室里面员工在游泳"
      },
      {
        "start": 139.32,
        "end": 140.4,
        "text": "然后Agent在干活"
      },
      {
        "start": 140.4,
        "end": 141.64,
        "text": "99%内容的"
      },
      {
        "start": 141.64,
        "end": 144.07999999999998,
        "text": "基本上都是干完货之后就直接扔掉了"
      },
      {
        "start": 144.07999999999998,
        "end": 144.84,
        "text": "这些交互啊"
      },
      {
        "start": 144.84,
        "end": 147.52,
        "text": "其实就是AI本身应该学习的工作经验"
      },
      {
        "start": 147.52,
        "end": 148.24,
        "text": "但现在呢"
      },
      {
        "start": 148.24,
        "end": 150.72,
        "text": "因为把这些内容干完就扔掉了"
      },
      {
        "start": 150.72,
        "end": 152.12,
        "text": "所以每次干活呢"
      },
      {
        "start": 152.12,
        "end": 153.28,
        "text": "都是得从领开始"
      },
      {
        "start": 153.28,
        "end": 155.28,
        "text": "Charjector那想改变了就是这件事情"
      },
      {
        "start": 155.28,
        "end": 156.07999999999998,
        "text": "第二件事情呢"
      },
      {
        "start": 156.07999999999998,
        "end": 157,
        "text": "他们聊到了说"
      },
      {
        "start": 157,
        "end": 158.76,
        "text": "既然上面说的经验很重要"
      },
      {
        "start": 158.76,
        "end": 159.88,
        "text": "那怎么去捕捉呢"
      },
      {
        "start": 159.88,
        "end": 160.32,
        "text": "第一步呢"
      },
      {
        "start": 160.32,
        "end": 161.88,
        "text": "就是要去完整的追踪"
      },
      {
        "start": 161.88,
        "end": 162.44,
        "text": "很多公司啊"
      },
      {
        "start": 162.44,
        "end": 164.04,
        "text": "只记录Agent的主流程"
      },
      {
        "start": 164.04,
        "end": 165.07999999999998,
        "text": "只Agent的调用"
      },
      {
        "start": 165.07999999999998,
        "end": 165.88,
        "text": "工具调用"
      },
      {
        "start": 165.88,
        "end": 166.92000000000002,
        "text": "然后全部都会扔掉了"
      },
      {
        "start": 166.92000000000002,
        "end": 169.36,
        "text": "Charjector说的是要趁死的后退"
      },
      {
        "start": 169.36,
        "end": 171.24,
        "text": "就是把整颗的行为数都记下了"
      },
      {
        "start": 171.24,
        "end": 172.28,
        "text": "那调不跟关键"
      },
      {
        "start": 172.28,
        "end": 175.6,
        "text": "就大多数产品的就是靠点赞收藏"
      },
      {
        "start": 175.6,
        "end": 177,
        "text": "这些去收集反馈"
      },
      {
        "start": 177,
        "end": 178.04,
        "text": "但实际上这些呢"
      },
      {
        "start": 178.04,
        "end": 178.72,
        "text": "几乎都没用"
      },
      {
        "start": 178.72,
        "end": 180.64,
        "text": "他们合作人说了一个很真实的观察"
      },
      {
        "start": 180.64,
        "end": 182.44,
        "text": "就是大家平时应该也用过"
      },
      {
        "start": 182.44,
        "end": 184.12,
        "text": "这个Agent有很多的正经历嘛"
      },
      {
        "start": 184.12,
        "end": 185.32,
        "text": "你基本上都是"
      },
      {
        "start": 185.32,
        "end": 187.32,
        "text": "他说什么就无脑同意同意同意"
      },
      {
        "start": 187.32,
        "end": 188.88,
        "text": "然后从一所有他的这个建议"
      },
      {
        "start": 188.88,
        "end": 190.36,
        "text": "那直到第五个同意之后呢"
      },
      {
        "start": 190.36,
        "end": 191.08,
        "text": "突然发现说"
      },
      {
        "start": 191.08,
        "end": 191.2,
        "text": "哎呀"
      },
      {
        "start": 191.2,
        "end": 194.04,
        "text": "他好像不善着我整个的思路去走的"
      },
      {
        "start": 194.04,
        "end": 195.44,
        "text": "他把这些事情都搞砸了"
      },
      {
        "start": 195.44,
        "end": 196.68,
        "text": "然后你再回去重做"
      },
      {
        "start": 196.68,
        "end": 197.07999999999998,
        "text": "所以呢"
      },
      {
        "start": 197.07999999999998,
        "end": 198.07999999999998,
        "text": "这些同意"
      },
      {
        "start": 198.07999999999998,
        "end": 199,
        "text": "这些点赞"
      },
      {
        "start": 199,
        "end": 200.12,
        "text": "其实没有什么性系量的"
      },
      {
        "start": 200.12,
        "end": 201.36,
        "text": "真正有价值的是"
      },
      {
        "start": 201.36,
        "end": 203.32,
        "text": "你后来回去改了什么东西"
      },
      {
        "start": 203.32,
        "end": 204.36,
        "text": "编辑了什么东西"
      },
      {
        "start": 204.36,
        "end": 205.92000000000002,
        "text": "然后重做了什么东西"
      },
      {
        "start": 205.92000000000002,
        "end": 207.12,
        "text": "呃取消了什么东西"
      },
      {
        "start": 207.12,
        "end": 208.16,
        "text": "这些纠正行为"
      },
      {
        "start": 208.16,
        "end": 209.64,
        "text": "才是真正的黄金信号"
      },
      {
        "start": 209.64,
        "end": 210.04,
        "text": "为什么呢"
      },
      {
        "start": 210.04,
        "end": 211.16,
        "text": "因为他不光告诉你"
      },
      {
        "start": 211.16,
        "end": 211.76,
        "text": "这里错了"
      },
      {
        "start": 211.76,
        "end": 212.28,
        "text": "这里对了"
      },
      {
        "start": 212.28,
        "end": 214.04,
        "text": "他还告诉你正确的答案"
      },
      {
        "start": 214.04,
        "end": 215.32,
        "text": "应该是长什么样子的"
      },
      {
        "start": 215.32,
        "end": 215.88,
        "text": "看到这里呢"
      },
      {
        "start": 215.88,
        "end": 217.16,
        "text": "我觉得对我们的起发是什么"
      },
      {
        "start": 217.16,
        "end": 218.88,
        "text": "就是对于我们做AI产品来说"
      },
      {
        "start": 218.88,
        "end": 220.16,
        "text": "你的产品交互里面"
      },
      {
        "start": 220.16,
        "end": 222.52,
        "text": "应该天然就包含这些纠正的动作"
      },
      {
        "start": 222.52,
        "end": 223.36,
        "text": "用户改了什么"
      },
      {
        "start": 223.36,
        "end": 224.16,
        "text": "撤销了什么"
      },
      {
        "start": 224.16,
        "end": 225,
        "text": "重视的时候呢"
      },
      {
        "start": 225,
        "end": 225.72,
        "text": "这些信号"
      },
      {
        "start": 225.72,
        "end": 226.92000000000002,
        "text": "就自动能够踩击到了"
      },
      {
        "start": 226.92000000000002,
        "end": 227.68,
        "text": "第三点呢"
      },
      {
        "start": 227.68,
        "end": 231.28,
        "text": "Traditional彈道的时候我这些经验也捕捉到了之后"
      },
      {
        "start": 231.28,
        "end": 232.07999999999998,
        "text": "然后呢应该干什么呢"
      },
      {
        "start": 232.07999999999998,
        "end": 234,
        "text": "这就是我觉得这个整片的分享里面"
      },
      {
        "start": 234,
        "end": 235.48,
        "text": "最有意思最干货的部分"
      },
      {
        "start": 235.48,
        "end": 236.48,
        "text": "是学道的东西呢"
      },
      {
        "start": 236.48,
        "end": 238.68,
        "text": "不是一股脑的塞进模型里面就完事了"
      },
      {
        "start": 238.68,
        "end": 239.88,
        "text": "你得决定说"
      },
      {
        "start": 239.88,
        "end": 241.88,
        "text": "指使更新到具体的哪个部分"
      },
      {
        "start": 241.88,
        "end": 244.4,
        "text": "Traditional彈道把整件事情分成了三层"
      },
      {
        "start": 244.4,
        "end": 245,
        "text": "第一层呢"
      },
      {
        "start": 245,
        "end": 246.88,
        "text": "就是全局通用的这种规律"
      },
      {
        "start": 246.88,
        "end": 249.48,
